// Inter (Latin-1 + Latin Extended-A + ponctuation + symboles) pour jsPDF
// https://rsms.me/inter/ (SIL Open Font License 1.1)
// Les plages couvrent Ø, ×, °, ², ½, œ, €, — … : un glyphe absent fait
// disparaitre silencieusement tout le fragment de texte dans le PDF.
window.INTER_REGULAR_B64="";
window.INTER_BOLD_B64="";
window.registerInter=function(doc){
  try{
    doc.addFileToVFS('Inter-Regular.ttf',window.INTER_REGULAR_B64);
    doc.addFont('Inter-Regular.ttf','Inter','normal');
    doc.addFileToVFS('Inter-Bold.ttf',window.INTER_BOLD_B64);
    doc.addFont('Inter-Bold.ttf','Inter','bold');
    return true;
  }catch(e){return false;}
};
